import { type FlameKeyframe, zeroKeyframe } from "@repo/arkit-flame";

/**
 * FLAME keyframes generated by the voice worker (`utils/flame/wire.py`).
 *
 * Topic `avatar.flame`, little-endian binary:
 *   header (26 B): "FLM1" | turn_id[12] | u32 startFrame | u16 nFrames |
 *                  u8 fps | u8 flags (bit0 = final) | u16 cols
 *   body: nFrames × cols float16 — expression[100], jawPose[3], speech gate.
 * Frame i describes audio time i / fps, on the same clock as the phonemes.
 */
export const FLAME_TOPIC = "avatar.flame";

const HEADER_BYTES = 26;
const EXPRESSION_DIMS = 100;
const JAW_DIMS = 3;
const MIN_COLS = EXPRESSION_DIMS + JAW_DIMS + 1;

export type FlamePacket = {
	turnId: string;
	startFrame: number;
	fps: number;
	final: boolean;
	cols: number;
	frames: Float32Array[];
};

export type FlameSample = {
	keyframe: FlameKeyframe;
	/** Speech gate 0..1 (0 = silence → idle owns the mouth). */
	gate: number;
};

function halfToFloat(h: number): number {
	const sign = h & 0x8000 ? -1 : 1;
	const exp = (h >> 10) & 0x1f;
	const frac = h & 0x3ff;
	if (exp === 0) return sign * 2 ** -14 * (frac / 1024);
	if (exp === 0x1f)
		return frac ? Number.NaN : sign * Number.POSITIVE_INFINITY;
	return sign * 2 ** (exp - 15) * (1 + frac / 1024);
}

export function parseFlamePacket(data: Uint8Array): FlamePacket | null {
	if (data.byteLength < HEADER_BYTES) return null;
	if (
		data[0] !== 0x46 || // F
		data[1] !== 0x4c || // L
		data[2] !== 0x4d || // M
		data[3] !== 0x31 // 1
	) {
		return null;
	}
	const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
	let turnId = "";
	for (let i = 4; i < 16 && data[i] !== 0; i++) {
		turnId += String.fromCharCode(data[i]);
	}
	const startFrame = view.getUint32(16, true);
	const n = view.getUint16(20, true);
	const fps = view.getUint8(22);
	const flags = view.getUint8(23);
	const cols = view.getUint16(24, true);
	if (cols < MIN_COLS || fps === 0) return null;
	if (data.byteLength < HEADER_BYTES + n * cols * 2) return null;

	const frames: Float32Array[] = [];
	let off = HEADER_BYTES;
	for (let i = 0; i < n; i++) {
		const row = new Float32Array(cols);
		for (let c = 0; c < cols; c++, off += 2) {
			const v = halfToFloat(view.getUint16(off, true));
			row[c] = Number.isFinite(v) ? v : 0;
		}
		frames.push(row);
	}
	return { turnId, startFrame, fps, final: (flags & 1) === 1, cols, frames };
}

/**
 * How long after the worker's `audio_start` marker the audio is actually
 * heard (publish queue + network + jitter buffer). Tune in the browser with
 * localStorage.optimodelFlameDelay (milliseconds) while watching a real call.
 */
const DEFAULT_AUDIO_LATENCY_MS = 150;

function audioLatencyMs(): number {
	try {
		const raw = window.localStorage.getItem("optimodelFlameDelay");
		const v = raw === null ? Number.NaN : Number(raw);
		return Number.isFinite(v) ? v : DEFAULT_AUDIO_LATENCY_MS;
	} catch {
		return DEFAULT_AUDIO_LATENCY_MS;
	}
}

/**
 * One speech turn of worker-generated frames, played on the wall clock.
 *
 * Message flow (see voice/worker/utils/lipsync_bridge.py):
 *   turn_start → flame packets (usually ahead of the audio) → audio_start
 *   → … → turn_end
 * `audio_start` is published the moment the first audio frame is played out,
 * so frame i is due `i / fps` seconds after it (plus the audio latency).
 * The browser plays the audio itself; there is no clock to keep in sync.
 */
export class FlameFeed {
	private turnId: string | null = null;
	private fps = 25;
	private frames: (Float32Array | undefined)[] = [];
	private lastIndex = -1;
	private final = false;
	private ended = false;
	private anchorMs: number | null = null;

	/** `turn_start`: drop the previous turn and collect frames for this one. */
	begin(turnId: string): void {
		this.turnId = turnId;
		this.frames = [];
		this.lastIndex = -1;
		this.final = false;
		this.ended = false;
		this.anchorMs = null;
	}

	/** `audio_start`: frame 0 is on screen when the audio is heard. */
	audioStart(turnId: string, nowMs = performance.now()): void {
		if (turnId !== this.turnId || this.ended) return;
		this.anchorMs = nowMs + audioLatencyMs();
	}

	/** `turn_end` (or an interruption): hand the mouth back to idle. */
	end(turnId?: string): void {
		if (turnId !== undefined && turnId !== this.turnId) return;
		this.ended = true;
		this.anchorMs = null;
	}

	/** Frames for any turn other than the current one are ignored. */
	push(packet: FlamePacket): void {
		if (packet.turnId !== this.turnId || this.ended) return;
		this.fps = packet.fps;
		packet.frames.forEach((row, i) => {
			const idx = packet.startFrame + i;
			this.frames[idx] = row;
			if (idx > this.lastIndex) this.lastIndex = idx;
		});
		if (packet.final) this.final = true;
	}

	/**
	 * Keyframe to show now, or null when the mouth should be idle: audio not
	 * started, frames not here yet, or the turn is over. If playback outruns
	 * the network the last frame is held until the final packet arrives.
	 */
	sample(nowMs = performance.now()): FlameSample | null {
		if (this.anchorMs === null || this.lastIndex < 0) return null;
		const pos = ((nowMs - this.anchorMs) / 1000) * this.fps;
		if (pos < 0) return null;
		const i0 = Math.floor(pos);
		if (i0 > this.lastIndex) {
			if (this.final) return null;
			return toSample(this.frames[this.lastIndex], undefined, 0);
		}
		return toSample(this.frames[i0], this.frames[i0 + 1], pos - i0);
	}
}

function toSample(
	a: Float32Array | undefined,
	b: Float32Array | undefined,
	t: number,
): FlameSample | null {
	if (!a) return null;
	const next = b ?? a;
	const at = (c: number) => a[c] + (next[c] - a[c]) * t;
	const keyframe = zeroKeyframe();
	for (let i = 0; i < EXPRESSION_DIMS; i++) keyframe.expression[i] = at(i);
	for (let i = 0; i < JAW_DIMS; i++) {
		keyframe.jawPose[i] = at(EXPRESSION_DIMS + i);
	}
	return { keyframe, gate: at(EXPRESSION_DIMS + JAW_DIMS) };
}
